const portraitStyles=document.createElement('link');portraitStyles.rel='stylesheet';portraitStyles.href='portrait.css';document.head.append(portraitStyles);
const projects=[
{slug:'microsoft-edge',name:'Microsoft Edge',title:'Making settings easier to find.',category:'Product analytics · Consumer products',accent:'#2577a7',wash:'#eaf2f6',role:'Product Manager Intern',date:'Jul 2024 – Mar 2025',tags:['Behavioral analysis','User research','Product decisions'],desc:'Connecting behavioral signals and user research to a more discoverable mobile experience.',impact:'22% fewer related complaints',note:'Post-launch observation, not an A/B treatment effect.',sections:[['The question','When people struggle to find a setting, is the problem the feature—or the way the product organizes it? I investigated discoverability in Edge Mobile by bringing together behavioral data, support feedback, and usability research.'],['My contribution','I diagnosed the problem, benchmarked competing experiences, and helped shape and validate a task-based information architecture. My work connected quantitative signals with the language and expectations of real users.'],['The analysis',['Behavioral data covering 3M+ users helped establish the scale of the experience.','Three months of support tickets added context to the observed friction.','An eight-browser benchmark informed alternative approaches.','A 20-user study helped validate discoverability and the proposed organization.']],['The decision','Organize settings around the tasks users are trying to complete. The analysis supported a task-based redesign and its validation before launch.'],['The outcome','After launch, related complaints fell 22% and module exit rate decreased approximately 16%. These are observed post-launch changes; the work did not establish causality through a randomized A/B test.'],['What I take forward','Behavioral data can show where an experience breaks down. Pairing it with support feedback and usability work helps explain why—and points toward a product change.']]},
{slug:'anyint-smart-routing',name:'AnyInt · Smart Routing',title:'Choosing a model should not be the hard part.',category:'AI product · Evaluation',accent:'#7651bd',wash:'#f0ecf8',role:'Product discovery & routing evaluation',date:'May – Sep 2026',tags:['Evaluation design','Quality–cost trade-offs','AI product'],desc:'Turning model-selection complexity into a measurable quality and cost decision.',impact:'~53% lower inference cost',note:'Evaluation versus the best single-model baseline.',sections:[['The question','How can an AI gateway help people choose an appropriate model without requiring them to compare providers, prices, and capabilities on every request?'],['My contribution','I synthesized discovery findings, helped define routing requirements, and designed and evaluated the routing approach. The work linked product priorities to measurable model-selection outcomes.'],['The analysis',['Conversations with approximately 50 AI practitioners and research into 8–10 competing platforms surfaced model-selection complexity and fragmented workflows.','The routing evaluation used 10,000 cases across five task categories.','Intent-and-difficulty accuracy, Top-2 Oracle Hit Rate, and non-regression measured different parts of routing quality.','Cost was evaluated against the best single-model baseline.']],['The decision','Treat routing as a quality-and-cost trade-off rather than optimizing price alone. Measure whether routing understands a task, identifies a strong candidate, and preserves quality relative to the comparison baseline.'],['The outcome','The evaluation reported 96% intent-and-difficulty accuracy, 82% Top-2 Oracle Hit Rate, and 90% non-regression, with approximately 53% lower inference cost than the best single-model baseline. These are evaluation results, not a claim of measured customer adoption or revenue impact.'],['What I take forward','An AI product decision needs an evaluation that reflects the user’s actual trade-offs. A single aggregate accuracy score cannot explain quality, cost, and routing failures on its own.']]},
{slug:'tesla-sales-analytics',name:'Tesla · Sales Analytics',title:'From scattered reports to a clearer sales funnel.',category:'Business analytics · Operations',accent:'#b84c35',wash:'#f7eeea',role:'Business Analyst Intern',date:'Jan – Mar 2024',tags:['Funnel analysis','Reporting automation','Power BI'],desc:'Making sales performance easier to monitor across 30+ Shanghai stores.',impact:'4+ hours → ~1 hour',note:'Reported preparation time for weekly reporting.',sections:[['The question','How can store and regional teams get a consistent view of sales performance without spending hours preparing reports? My work focused on visibility across the funnel, from lead sources to delivery.'],['My contribution','I automated intraday and weekly reporting and supported sales-performance and location analysis. The work combined reporting operations with analysis that managers could use in follow-up, staffing, and planning discussions.'],['The analysis',['Tracked performance across leads, appointments, test drives, orders, and deliveries.','Used Excel and Power Automate for reporting and automation.','Analyzed weekly funnel performance and monthly trends to identify gaps in appointment attendance and sales productivity.','Used Python and Power BI to combine sales, target-customer, geographic-coverage, and competitor-location data from 7–8 automotive brands for pop-up site planning.']],['The decision','Give regional and store teams a consistent view of performance, then use funnel and geographic comparisons to support operational priorities. Site analysis supported planning for three suburban pop-up locations.'],['The outcome','The reporting work covered 30+ Shanghai stores and reduced preparation time from more than four hours to approximately one hour. The value was faster reporting and clearer decision support; this case does not attribute sales growth to the dashboards.'],['What I take forward','The usefulness of a dashboard depends on the decisions it supports. Reporting automation creates time for analysis, while consistent funnel definitions make comparisons more actionable.']]},
{slug:'universal-agent-benchmark',name:'Universal Agent Benchmark',title:'What does “better” mean for an AI agent?',category:'AI evaluation · Research',accent:'#42836a',wash:'#eaf2ec',role:'Evaluation research',date:'Research project',tags:['Benchmark methodology','Failure analysis','AI evaluation'],desc:'Exploring how to compare agent performance with a consistent evaluation framework.',impact:'A closer look at evaluation',note:'Methodology overview; detailed study artifacts to follow.',sections:[['The question','Comparing AI agents requires a clear definition of success. This research project explores how task design and evaluation criteria shape what a benchmark can tell us.'],['The project lens','The portfolio overview focuses on evaluation methodology: what is being compared, which conditions are held consistent, and how failures should be interpreted.'],['What to examine',['Task definition and success criteria.','Consistency of evaluation conditions.','How aggregate results relate to individual failure cases.','The limits of conclusions supported by the study.']],['Project materials','A detailed study walkthrough and supporting artifacts will be added after the original research materials are reviewed. This overview does not report benchmark scores or rank frameworks.']]}
];
const additionalWork=[
{name:'Xiaohongshu · Model Evaluation',type:'Data product experience',year:'2023',desc:'Built a category-level evaluation framework for sentiment and classification outputs, then traced a metric anomaly to entity-disambiguation errors.',tags:['Offline evaluation','Root-cause analysis','Annotation rules']},
{name:'BNY · Public Narrative Analysis',type:'Business analytics project',year:'2026',desc:'Refined Brandwatch queries and benchmarked visibility, sentiment, and audience engagement across BNY and custodian peers.',tags:['Query design','Competitive analysis','Decision support']},
{name:'AI Disclosure Experiment',type:'CMU coursework project',year:'2026',desc:'Co-designed a randomized experiment with 85 graduate students and analyzed how AI attribution changed perceived expertise and credibility.',tags:['A/B testing','Statistical inference','Treatment effects']}
];
const main=document.querySelector('main');
function art(p){let body='';if(p.slug==='microsoft-edge')body='<div class="settings"><div class="phone"><b>Settings</b><div>Account</div><div>Privacy & security</div><div>Appearance</div><div>Accessibility</div></div><div class="insight"><div class="big">−22%</div><p>related complaints<br>after launch</p><div class="mini-bars"><i style="height:36px"></i><i style="height:29px"></i><i style="height:23px"></i></div><small>Discoverability matters.</small></div></div>';else if(p.slug==='anyint-smart-routing')body='<div class="router"><div class="node">Your task</div><span>→</span><div class="node active">Smart<br>Routing</div><span>→</span><div class="models"><span>Model A</span><span>Model B</span><span>Model C</span></div></div><div class="viz-bottom"><span>Quality-aware selection</span><b>~53% lower cost</b></div>';else if(p.slug==='tesla-sales-analytics')body='<div class="tesla-body"><div class="funnel"><div style="width:100%">Leads</div><div style="width:88%">Appointments</div><div style="width:76%">Test drives</div><div style="width:64%">Orders</div><div style="width:52%">Deliveries</div></div><div class="metric-box"><small>WEEKLY PREPARATION</small><div class="big">4+ → 1h</div><p>30+ stores<br>One consistent view.</p></div></div>';else body='<div class="matrix"><span>Evaluation lens</span><span>Task</span><span>Quality</span><span>Failure</span><span>Define</span><i></i><i></i><i></i><span>Compare</span><i></i><i></i><i></i><span>Inspect</span><i></i><i></i><i></i></div><div class="viz-bottom"><span>Consistent conditions.</span><span>Interpretable results.</span></div>';return `<div class="viz"><div class="viz-top"><b>${p.name}</b><span>ANALYSIS NOTES / 0${projects.indexOf(p)+1}</span></div>${body}</div>`}
function card(p,i){return `<article class="project" style="--accent:${p.accent};--wash:${p.wash}"><a class="stage" href="work/${p.slug}/" aria-label="Read ${p.name} case study"><div class="stack"><div class="sheet back"></div><div class="sheet middle"></div><div class="sheet front">${art(p)}</div></div></a><div class="project-meta"><h2><a href="work/${p.slug}/">${p.name}</a></h2><a class="arrow" href="work/${p.slug}/" aria-label="Read ${p.name}">↗</a></div><p>${p.desc}</p><div class="tags">${p.tags.map(t=>`<span>${t}</span>`).join('')}</div></article>`}
const links='<a class="text-link" href="https://www.linkedin.com/in/chloeruoyuxu" target="_blank" rel="noopener">LinkedIn ↗</a>';
function home(){main.innerHTML=`<section class="hero"><div class="intro"><img class="avatar" src="assets/chloe-portrait.jpg" alt="Portrait of Chloe Ruoyu Xu"><div><strong>Chloe Ruoyu Xu</strong><small>Product & data analytics · Carnegie Mellon</small></div></div><h1>I connect <em>user behavior,</em><br>product questions, and data<br>to find what teams should<br>build next.</h1><p class="subtitle">Exploring the why behind the numbers.<br>Across consumer products, AI systems, and business operations.</p><div class="actions"><a class="primary" href="#work">Explore my work ↓</a><a class="text-link" href="resume.pdf" target="_blank" rel="noopener">View résumé ↗</a></div><span class="hero-note">PEOPLE × PRODUCTS × DATA</span></section><section class="work" id="work"><div class="section-label"><span>Selected work / 01—04</span><span>Different questions. A shared curiosity.</span></div><div class="grid">${projects.map(card).join('')}</div><div class="more"><div><h3>There’s more behind these four stories.</h3><p>Explore additional experience, analysis projects, and coursework.</p></div><a class="text-link" href="work/">View all work ↗</a></div></section>`;setNav('home')}
function work(){document.title='Work — Chloe Ruoyu Xu';document.querySelector('meta[name="description"]').content='Selected product, data, business analytics, and AI evaluation work by Chloe Ruoyu Xu.';main.innerHTML=`<article class="work-page"><section class="work-intro"><p class="eyebrow">Work</p><h1>Questions I’ve explored<br>through products and data.</h1><p class="lead">A collection of product decisions, analytical systems, evaluation research, and experiments.</p></section><section class="work all-work"><div class="section-label"><span>Featured case studies / 01—04</span><span>Full stories, methods, and outcomes.</span></div><div class="grid">${projects.map(card).join('')}</div></section><section class="additional-work"><div class="section-label"><span>Additional work</span><span>Experience, projects, and coursework.</span></div>${additionalWork.map(item=>`<article class="work-row"><div><span class="work-type">${item.type} · ${item.year}</span><h2>${item.name}</h2></div><div><p>${item.desc}</p><div class="tags">${item.tags.map(tag=>`<span>${tag}</span>`).join('')}</div></div></article>`).join('')}</section></article>`;setNav('work')}
function setNav(n){document.querySelector(`[data-nav="${n}"]`)?.classList.add('active')}
function detail(p){document.title=`${p.name} — Chloe Ruoyu Xu`;document.querySelector('meta[name="description"]').content=p.desc;main.innerHTML=`<article class="page" style="--accent:${p.accent};--wash:${p.wash}"><a class="text-link" href="work/">← All work</a><p class="eyebrow">${p.category}</p><h1>${p.title}</h1><p class="lead">${p.desc}</p><div class="facts"><div><small>Project</small><span>${p.name}</span></div><div><small>Contribution</small><span>${p.role}</span></div><div><small>When</small><span>${p.date}</span></div></div><div class="case-art">${art(p)}<div><h2>${p.impact}</h2><p>${p.note}</p></div></div><p class="caption">Recreated diagram for this case study. Illustrative layout; not an original company interface. Funnel widths and decorative marks do not represent underlying data.</p>${p.sections.map(([title,body])=>`<section class="case-section"><h2>${title}</h2><div>${Array.isArray(body)?'<ul>'+body.map(x=>`<li>${x}</li>`).join('')+'</ul>':`<p>${body}</p>`}</div></section>`).join('')}<div class="next"><a href="work/">← Back to work</a><a href="work/${projects[(projects.indexOf(p)+1)%4].slug}/">Next project ↗</a></div></article>`;setNav('work')}
function about(){document.title='About — Chloe Ruoyu Xu';main.innerHTML=`<article class="page"><div class="about-hero"><div class="about-copy"><p class="eyebrow">A little about me</p><h1>Hi, I’m Chloe.<br>I like asking why.</h1><p class="lead">I connect user behavior, product questions, and data to find what teams should build next.</p><p class="lead">I’m pursuing a Master of Information Systems Management, focused on Business Intelligence and Data Analytics, at Carnegie Mellon University. I’m looking for product and data analyst opportunities where thoughtful analysis shapes real decisions.</p></div><figure class="portrait-frame"><img src="assets/chloe-portrait.jpg" alt="Chloe Ruoyu Xu"><figcaption>Product × Data × AI</figcaption></figure></div><div class="about-grid"><section class="about-card"><h2>People → questions → evidence</h2><p>My experience spans consumer-product analysis at Microsoft, sales reporting at Tesla, and AI product evaluation at AnyInt. I’m interested in both the human context of a problem and the analytical work needed to understand it.</p></section><section class="about-card"><h2>My toolkit</h2><p>SQL · Python · Power BI · Tableau · Excel</p><p>Funnel and behavioral analysis, experimentation, statistical inference, user research, and model evaluation.</p></section><section class="about-card"><h2>Carnegie Mellon University</h2><p>MISM · Business Intelligence & Data Analytics<br>Aug 2025 – Dec 2026 (expected)</p></section><section class="about-card"><h2>Xi’an Jiaotong-Liverpool University</h2><p>Information Management & Information Systems<br>Sep 2021 – Jul 2025</p></section></div><div class="actions">${links}<a class="text-link" href="resume.pdf" target="_blank" rel="noopener">Résumé ↗</a></div></article>`;setNav('about')}
function contact(){document.title='Contact — Chloe Ruoyu Xu';main.innerHTML=`<article class="page"><p class="eyebrow">Say hello</p><h1>Have a good question?<br>I’d love to hear it.</h1><p class="lead">For product and data opportunities, interesting projects, or a conversation about the work.</p><div style="margin-top:55px"><a class="contact-row" href="mailto:ruoyux@andrew.cmu.edu"><span>ruoyux@andrew.cmu.edu</span><span>↗</span></a><a class="contact-row" href="https://www.linkedin.com/in/chloeruoyuxu" target="_blank" rel="noopener"><span>Connect on LinkedIn</span><span>↗</span></a><a class="contact-row" href="resume.pdf" target="_blank" rel="noopener"><span>View my résumé</span><span>↗</span></a></div></article>`;setNav('contact')}
const basePath=location.hostname.endsWith('github.io')?'/personal-site':'';const path=location.pathname.slice(basePath.length).replace(/\/$/,'');const match=projects.find(p=>path===`/work/${p.slug}`);if(match)detail(match);else if(path==='/work')work();else if(path==='/about')about();else if(path==='/contact')contact();else if(path==='')home();else{document.title='Page not found — Chloe Ruoyu Xu';main.innerHTML='<section class="page"><h1>This page took a detour.</h1><a class="text-link" href="./">Return home →</a></section>'}
